public class CategoryPlot_getDomainAxisIndex_TriageGen2Test {

    private CategoryPlot plot;
    private CategoryDataset dataset;
    private CategoryAxis axis1;
    private CategoryAxis axis2;
    private ValueAxis rangeAxis;
    private CategoryItemRenderer renderer;

    @Before
    public void setUp() {
        dataset = Mockito.mock(CategoryDataset.class);
        axis1 = Mockito.mock(CategoryAxis.class);
        axis2 = Mockito.mock(CategoryAxis.class);
        rangeAxis = Mockito.mock(ValueAxis.class);
        renderer = Mockito.mock(CategoryItemRenderer.class);
        plot = new CategoryPlot(dataset, axis1, rangeAxis, renderer);
    }

    @Test
    public void testGetDomainAxisIndex_SingleAxis_ReturnsZero() {
        // Default constructor with one axis sets index 0
        int index = plot.getDomainAxisIndex(axis1);
        assertEquals("Index of the primary domain axis should be 0", 0, index);
    }

    @Test
    public void testGetDomainAxisIndex_MultipleAxes_ReturnsCorrectIndex() {
        // Set up multiple domain axes
        CategoryAxis[] axes = new CategoryAxis[]{axis1, axis2};
        plot.setDomainAxes(axes);

        int index1 = plot.getDomainAxisIndex(axis1);
        int index2 = plot.getDomainAxisIndex(axis2);

        assertEquals("First axis should be at index 0", 0, index1);
        assertEquals("Second axis should be at index 1", 1, index2);
    }

    @Test
    public void testGetDomainAxisIndex_AxisNotFound_ReturnsNegativeOne() {
        CategoryAxis unknownAxis = Mockito.mock(CategoryAxis.class);

        // axis1 is in the plot, unknownAxis is not
        int index = plot.getDomainAxisIndex(unknownAxis);

        assertEquals("Index of an axis not present in the plot should be -1", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_AfterClearingAxes_ReturnsNegativeOne() {
        plot.clearDomainAxes();

        int index = plot.getDomainAxisIndex(axis1);

        assertEquals("Index should be -1 after all domain axes are cleared", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_AfterUpdatingAxis_ReturnsCorrectIndex() {
        // Replace axis1 with axis2 at index 0
        plot.setDomainAxis(0, axis2);

        int indexOld = plot.getDomainAxisIndex(axis1);
        int indexNew = plot.getDomainAxisIndex(axis2);

        assertEquals("Old axis should no longer be found", -1, indexOld);
        assertEquals("New axis should be at index 0", 0, indexNew);
    }
}
